/* One planning controller: switches never render an intermediate view or refetch. */
(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;
const DAY=86400000,iso=n=>new Date(n).toISOString().slice(0,10),stamp=s=>Date.parse(s+'T12:00:00Z');
let mode='calendar',from='',to='',activeProject=null,cached=[],loaded=0,inflight=null;
const compact=s=>new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(stamp(s)));
function defaults(){const p=SamandisDates.display(iso(Date.now())).split('/').map(Number);from=SamandisDates.parse(p[0]+'/'+p[1]+'/1');let last=29;for(let i=30;i<=31;i++)if(SamandisDates.parse(p[0]+'/'+p[1]+'/'+i))last=i;to=SamandisDates.parse(p[0]+'/'+p[1]+'/'+last)}
function valid(){return scope==='program'&&project?.id===activeProject&&!window.SAMANDIS_PERSONAL_MODE}
function taskRows(){return [...tasks.filter(t=>t.due).map(t=>({id:t.id,title:t.title,start:(t.starts_on||t.created_at||t.due).slice(0,10),due:t.due,status:labels[t.status],done:t.status==='done'})),...cached.map(m=>({id:m.id,title:m.title,start:m.starts_on||m.due,due:m.due,status:'تحویل پروژه',delivery:true}))]}
function action(r,extra=''){return '<button type="button" class="'+extra+'" data-plan-id="'+esc(r.id)+'" data-plan-delivery="'+!!r.delivery+'">'+esc(r.title)+'</button>'}
function calendar(rows){const lo=stamp(from),hi=stamp(to),offset=(new Date(lo).getUTCDay()+1)%7,days=Math.round((hi-lo)/DAY)+1;let cells=Array(offset).fill('<div class="plan-day blank" aria-hidden="true"></div>').join('');for(let n=lo;n<=hi;n+=DAY){const key=iso(n),parts=SamandisDates.display(key).split('/');cells+='<div class="plan-day '+(key===iso(Date.now())?'today':'')+'"><time datetime="'+key+'" title="'+date(key)+'"><b>'+fa(Number(parts[2]))+'</b><small>'+compact(key).replace(/^[۰-۹0-9]+\s*/,'')+'</small></time>'+rows.filter(r=>r.due===key).map(r=>'<div class="plan-event '+(r.delivery?'delivery':r.done?'done':'')+'">'+action(r)+'</div>').join('')+'</div>'}cells+=Array((7-(offset+days)%7)%7).fill('<div class="plan-day blank" aria-hidden="true"></div>').join('');return '<div class="plan-calendar-scroll"><div class="plan-calendar">'+['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'].map(d=>'<div class="plan-weekday">'+d+'</div>').join('')+cells+'</div></div>'}
function gantt(rows){const lo=stamp(from),hi=stamp(to)+DAY,span=hi-lo,count=Math.round(span/DAY),position=n=>(n-lo)/span*100,visible=rows.filter(r=>stamp(r.due)>=lo&&Math.min(stamp(r.start),stamp(r.due))<hi),step=Math.max(1,Math.ceil(count/8));let ticks='';for(let i=0;i<count;i+=step)ticks+='<span style="right:'+i/count*100+'%">'+compact(iso(lo+i*DAY))+'</span>';const today=position(stamp(iso(Date.now())));return '<div class="plan-gantt-scroll"><div class="plan-gantt"><div class="plan-gantt-head"><div>کار / بازهٔ انجام</div><div class="plan-axis">'+ticks+'</div></div>'+visible.map(r=>{const start=Math.min(stamp(r.start),stamp(r.due)),a=Math.max(0,position(start)),b=Math.min(100,position(stamp(r.due)+DAY));return '<div class="plan-gantt-row"><div class="plan-gantt-label">'+action(r)+'<small>'+compact(r.start)+' — '+compact(r.due)+'</small><span class="plan-status '+(r.delivery?'delivery':r.done?'done':'')+'">'+esc(r.status)+'</span></div><div class="plan-track">'+(today>=0&&today<100?'<i class="plan-today" style="right:'+today+'%" title="امروز"></i>':'')+'<button class="plan-bar '+(r.delivery?'delivery':r.done?'done':'')+'" data-plan-id="'+esc(r.id)+'" data-plan-delivery="'+!!r.delivery+'" style="right:'+a+'%;width:'+(b-a)+'%" title="'+esc(r.title)+' · '+esc(r.status)+'" aria-label="'+esc(r.title)+' · '+esc(r.status)+'"></button></div></div>'}).join('')+'</div></div>'+(!visible.length?'<div class="plan-empty"><b>کار زمان‌بندی‌شده‌ای در این بازه نیست</b><p>بازه را تغییر دهید یا برای کارهای زیر مهلت تعیین کنید.</p></div>':'')}
function draw(){if(!valid())return;const root=el('#sharedContent'),focus=root.querySelector('[data-plan-mode]:focus')?.dataset.planMode,rows=taskRows(),undated=tasks.filter(t=>!t.due);root.innerHTML='<div class="plan-workspace"><div class="plan-toolbar"><div><h2>برنامهٔ پروژه</h2><p>'+date(from)+' تا '+date(to)+'</p></div><div class="plan-tabs" role="group" aria-label="نمای برنامه">'+[['calendar','تقویم'],['gantt','گانت']].map(([v,l])=>'<button type="button" data-plan-mode="'+v+'" aria-pressed="'+(mode===v)+'" class="'+(mode===v?'active':'')+'">'+l+'</button>').join('')+'</div></div><form id="programRange" class="range-controls"><label>از تاریخ<input type="date" name="from" value="'+from+'" required></label><label>تا تاریخ<input type="date" name="to" value="'+to+'" required></label><button class="primary">اعمال بازه</button><button type="button" id="planReset" class="secondary">ماه جاری</button><button type="button" id="planRefresh" class="text-btn">تازه‌سازی</button>'+(management()?'<button type="button" id="planDelivery" class="secondary">＋ تحویل پروژه</button>':'')+'</form><section class="plan-surface">'+(mode==='calendar'?calendar(rows):gantt(rows))+'</section><details class="plan-undated" '+(!rows.length?'open':'')+'><summary>'+fa(undated.length)+' کار بدون مهلت · تعیین زمان‌بندی</summary><p>برای نمایش روی گانت و تقویم، کار را باز کنید و از ویرایش، مهلت آن را مشخص کنید.</p>'+undated.map(t=>action(t,'plan-undated-task')).join('')+'</details><p class="shared-meta">تقویم: موعد تحویل · گانت: شروع تا مهلت (در نبود تاریخ شروع، تاریخ تعریف کار)</p></div>';
root.querySelectorAll('[data-plan-mode]').forEach(b=>b.onclick=()=>{const form=el('#programRange'),f=new FormData(form);if(!apply(f,false))return;mode=b.dataset.planMode;draw()});root.querySelectorAll('[data-plan-id]').forEach(b=>b.onclick=()=>b.dataset.planDelivery==='true'?window.SamandisMilestoneForm?.(cached.find(m=>m.id===b.dataset.planId)):detail(b.dataset.planId));el('#programRange').onsubmit=e=>{e.preventDefault();if(apply(new FormData(e.target),true))draw()};el('#planReset').onclick=()=>{defaults();draw()};el('#planRefresh').onclick=()=>{loaded=0;renderProgram()};if(el('#planDelivery'))el('#planDelivery').onclick=()=>window.SamandisMilestoneForm?.();if(focus)root.querySelector('[data-plan-mode="'+mode+'"]').focus()}
function apply(f,report){const a=f.get('from'),b=f.get('to');if(!a||!b||!Number.isFinite(stamp(a))||!Number.isFinite(stamp(b))||a>b){message('بازهٔ تاریخ معتبر نیست؛ شروع باید قبل از پایان باشد.');return false}if((stamp(b)-stamp(a))/DAY>365){message('بازه را حداکثر یک سال انتخاب کنید.');return false}from=a;to=b;return true}
renderProgram=function(force=false){const pid=project?.id;if(!pid)return Promise.resolve();if(force===true)loaded=0;if(activeProject===pid&&valid()){const draft=el("#programRange");if(draft){const f=new FormData(draft);if(f.get("from")!==from||f.get("to")!==to)return Promise.resolve()}}if(activeProject!==pid){activeProject=pid;cached=[];loaded=0;inflight=null;defaults()}draw();if(Date.now()-loaded<20000)return Promise.resolve();if(inflight)return inflight;inflight=checked(db.from('sm_milestones').select('*').eq('project_id',pid).order('due')).then(list=>{if(activeProject!==pid)return;cached=list;loaded=Date.now();if(valid()){const form=el('#programRange');if(form){const f=new FormData(form);if(f.get('from')!==from||f.get('to')!==to)return}draw()}}).catch(e=>{if(valid())message(failure(e))}).finally(()=>{if(activeProject===pid)inflight=null});return inflight};
})();
